import { auth } from "@/auth";
import { DUMMY_HASH, hashPassword, verifyPasswordHash } from "@/lib/password";

export type User = {
  id: string;
  email: string;
  name: string;
  createdAt: string;
};

type StoredUser = User & { passwordHash?: string };

// In-memory store (resets on restart). Seed users have no password, so they
// can only be reached by signing in with Google using the same verified email.
const users: StoredUser[] = [
  { id: "1", email: "ada@example.com", name: "Ada", createdAt: "2026-01-04" },
  { id: "2", email: "grace@example.com", name: "Grace", createdAt: "2026-02-11" },
];

const normalizeEmail = (email: string) => email.trim().toLowerCase();

function toPublic({ passwordHash: _omit, ...user }: StoredUser): User {
  return user;
}

export async function listUsers(): Promise<User[]> {
  return users.map(toPublic);
}

export async function getUser(id: string): Promise<User | undefined> {
  const u = users.find((u) => u.id === id);
  return u && toPublic(u);
}

export async function getUserByEmail(email: string): Promise<User | undefined> {
  const e = normalizeEmail(email);
  const u = users.find((u) => u.email === e);
  return u && toPublic(u);
}

export class EmailTakenError extends Error {}

export async function createUser(input: {
  email: string;
  name: string;
  password?: string;
}): Promise<User> {
  const email = normalizeEmail(input.email);
  if (users.some((u) => u.email === email)) throw new EmailTakenError();
  const user: StoredUser = {
    id: crypto.randomUUID(),
    email,
    name: input.name.trim(),
    createdAt: new Date().toISOString().slice(0, 10),
    passwordHash: input.password ? await hashPassword(input.password) : undefined,
  };
  users.push(user);
  return toPublic(user);
}

/** Returns the user if the email/password pair is valid, otherwise undefined. */
export async function verifyCredentials(email: string, password: string): Promise<User | undefined> {
  const e = normalizeEmail(email);
  const u = users.find((u) => u.email === e);
  const ok = await verifyPasswordHash(password, u?.passwordHash ?? DUMMY_HASH);
  return u && u.passwordHash && ok ? toPublic(u) : undefined;
}

/** Finds or creates the user for a Google account whose email Google has verified. */
export async function findOrCreateGoogleUser(profile: { email: string; name?: string | null }): Promise<User> {
  return (
    (await getUserByEmail(profile.email)) ??
    (await createUser({ email: profile.email, name: profile.name || profile.email.split("@")[0] }))
  );
}

export async function getCurrentUser(): Promise<User | undefined> {
  const session = await auth();
  return session?.user?.id ? getUser(session.user.id) : undefined;
}
EOF
